class TestChannelDefinitions:
    """Verify all 6 channels are defined correctly."""

    def test_has_six_channels(self):
        assert len(COMPLIANCE_CHANNELS) == 6

    def test_required_channels_exist(self):
        expected = {
            "compliance-status",
            "threat-intel",
            "compliance-alerts",
            "vendor-compliance",
            "access-requests",
            "datalake-pipeline",
        }
        assert set(COMPLIANCE_CHANNELS.keys()) == expected

    def test_channels_have_description(self):
        for name, ch in COMPLIANCE_CHANNELS.items():
            assert "description" in ch, f"{name} missing description"
            assert len(ch["description"]) > 10

    def test_channels_have_alert_levels(self):
        for name, ch in COMPLIANCE_CHANNELS.items():
            assert "alert_levels" in ch, f"{name} missing alert_levels"
            assert len(ch["alert_levels"]) > 0


