def _mock_json(key, data):
    """Context manager to mock a compliance JSON file."""
    from discord_ops.compliance_bot import _JSON_PATHS

    path = _JSON_PATHS.get(key, f"/tmp/test_{key}.json")
    tmp = tempfile.NamedTemporaryFile(mode="w", suffix=".json", delete=False)
    json.dump(data, tmp)
    tmp.close()
    return patch.dict(
        "discord_ops.compliance_bot._JSON_PATHS",
        {key: tmp.name},
    )


class TestReadComplianceJson:
    def test_reads_valid_json(self):
        with _mock_json("cmmc", {"score": 85}):
            data = read_compliance_json("cmmc")
            assert data == {"score": 85}

    def test_returns_none_for_missing_key(self):
        assert read_compliance_json("nonexistent_key") is None

    def test_returns_none_for_missing_file(self):
        with patch.dict(
            "discord_ops.compliance_bot._JSON_PATHS",
            {"test": "/tmp/does_not_exist_xyz.json"},
        ):
            assert read_compliance_json("test") is None


