class TestEscalation:
    def test_cui_urgent_escalates(self):
        assert should_escalate({"open": 1, "hours_until_deadline": 12}, "cui_incidents")

    def test_cui_not_urgent_no_escalation(self):
        assert not should_escalate({"open": 1, "hours_until_deadline": 48}, "cui_incidents")

    def test_cui_zero_open_no_escalation(self):
        assert not should_escalate({"open": 0, "hours_until_deadline": 6}, "cui_incidents")

    def test_critical_vuln_escalates(self):
        assert should_escalate({"critical": 1}, "vuln_scan")

    def test_no_critical_vuln_no_escalation(self):
        assert not should_escalate({"critical": 0}, "vuln_scan")

    def test_supply_chain_critical_escalates(self):
        assert should_escalate({"risk_tier": "critical"}, "supply_chain_risk")

    def test_supply_chain_low_no_escalation(self):
        assert not should_escalate({"risk_tier": "low"}, "supply_chain_risk")

    def test_threat_critical_escalates(self):
        assert should_escalate({"threat_tier": "critical"}, "threat_matrix")

    def test_siem_critical_escalates(self):
        assert should_escalate({"critical": 3}, "siem_alert")

    def test_vendor_noncompliant_escalates(self):
        assert should_escalate({"non_compliant": 2}, "vendor_compliance")


