class TestCommandBuilders:
    """Test each slash command builder with mock data."""

    def test_threat_posture_with_data(self):
        with _mock_json("threat_matrix", {
            "exploitable_techniques": 5,
            "critical_gaps": 2,
            "highest_risk_family": "SC",
            "threat_tier": "critical",
        }):
            alert = build_threat_posture()
            assert alert.severity == "critical"
            assert "5" in alert.description

    def test_threat_posture_no_data(self):
        with patch.dict("discord_ops.compliance_bot._JSON_PATHS", {"threat_matrix": "/tmp/nope.json"}):
            alert = build_threat_posture()
            assert alert.severity == "warning"
            assert "Unavailable" in alert.title

    def test_compliance_status_high_score(self):
        with _mock_json("cmmc", {"score": 95, "level": 2, "controls_met": 100, "controls_total": 110}):
            alert = build_compliance_status()
            assert alert.severity == "ok"

    def test_compliance_status_low_score(self):
        with _mock_json("cmmc", {"score": 40, "level": 1}):
            alert = build_compliance_status()
            assert alert.severity == "critical"

    def test_vuln_summary_critical(self):
        with _mock_json("vuln_scan", {"critical": 3, "high": 10, "medium": 25, "last_scan": "2026-02-23T10:00:00Z"}):
            alert = build_vuln_summary()
            assert alert.severity == "critical"
            assert "3" in alert.description

    def test_vuln_summary_stale(self):
        with _mock_json("vuln_scan", {"critical": 0, "high": 0, "medium": 5, "stale": True}):
            alert = build_vuln_summary()
            assert "STALE" in alert.title

    def test_vendor_status_all_certified(self):
        with _mock_json("vendor_compliance", {"certified": 10, "total": 10, "pending": 0, "non_compliant": 0, "expiring_30d": 0}):
            alert = build_vendor_status()
            assert alert.severity == "ok"

    def test_vendor_status_non_compliant(self):
        with _mock_json("vendor_compliance", {"certified": 8, "total": 10, "non_compliant": 2, "expiring_30d": 1}):
            alert = build_vendor_status()
            assert alert.severity == "critical"

    def test_supply_chain_critical(self):
        with _mock_json("supply_chain_risk", {
            "risk_tier": "critical",
            "compromised_vendors": 2,
            "cisa_advisories_affecting_bom": 1,
            "total_vendors": 500,
            "sbom_drift_count": 3,
            "suspicious_access": 1,
            "expired_attestations": 5,
        }):
            alert = build_supply_chain_status()
            assert alert.severity == "critical"
            assert "500" in alert.description

    def test_cui_urgent(self):
        with _mock_json("cui_incidents", {"open": 2, "hours_until_deadline": 8}):
            alert = build_cui_status()
            assert alert.severity == "critical"
            assert "URGENT" in alert.title

    def test_cui_no_incidents(self):
        with _mock_json("cui_incidents", {"open": 0, "hours_until_deadline": 72}):
            alert = build_cui_status()
            assert alert.severity == "ok"

    def test_poam_overdue(self):
        with _mock_json("poam", {"open": 5, "overdue": 2}):
            alert = build_poam_status()
            assert alert.severity == "critical"

    def test_sprs_score_good(self):
        with _mock_json("sprs_score", {"score": 95, "delta": 5}):
            alert = build_sprs_summary()
            assert alert.severity == "ok"
            assert "+5" in alert.description

    def test_sprs_score_bad(self):
        with _mock_json("sprs_score", {"score": 30, "delta": -10}):
            alert = build_sprs_summary()
            assert alert.severity == "critical"

    def test_drift_report(self):
        alert = build_drift_report()
        assert alert.severity == "info"

    def test_assessment_countdown_urgent(self):
        with _mock_json("assessment_countdown", {"days": 15, "readiness_pct": 60}):
            alert = build_assessment_countdown()
            assert alert.severity == "critical"

    def test_assessment_countdown_comfortable(self):
        with _mock_json("assessment_countdown", {"days": 120, "readiness_pct": 85}):
            alert = build_assessment_countdown()
            assert alert.severity == "ok"


