class TestComplianceAlert:
    def test_to_embed(self):
        alert = ComplianceAlert(
            channel="test",
            title="Test Alert",
            description="Something happened",
            severity="critical",
        )
        embed = alert.to_embed()
        assert embed["title"] == "Test Alert"
        assert embed["color"] == 0xE74C3C

    def test_to_dict(self):
        alert = ComplianceAlert(
            channel="test",
            title="T",
            description="D",
            severity="info",
        )
        d = alert.to_dict()
        assert d["channel"] == "test"
        assert d["severity"] == "info"

    def test_auto_timestamp(self):
        alert = ComplianceAlert(channel="t", title="T", description="D", severity="info")
        assert alert.timestamp  # auto-populated


class TestComplianceReport:
    def test_daily_digest(self):
        # Build with all missing data (returns warnings for each)
        with patch.dict("discord_ops.compliance_bot._JSON_PATHS", {
            k: "/tmp/nope.json" for k in [
                "cmmc", "threat_matrix", "vuln_scan", "vendor_compliance",
                "cui_incidents", "poam",
            ]
        }):
            report = build_daily_digest()
            assert report.report_type == "daily_digest"
            assert len(report.embeds) == 6  # One embed per source
            assert len(report.alerts) == 6

    def test_weekly_summary(self):
        with patch.dict("discord_ops.compliance_bot._JSON_PATHS", {
            k: "/tmp/nope.json" for k in [
                "cmmc", "sprs_score", "threat_matrix", "vuln_scan",
                "supply_chain_risk", "vendor_compliance", "cui_incidents",
                "poam", "assessment_countdown",
            ]
        }):
            report = build_weekly_summary()
            assert report.report_type == "weekly_summary"
            assert len(report.embeds) == 9


